package com.cashflow.app.engine

import java.time.LocalDate

/** What deleting one item does to storage. */
sealed interface DeleteOutcome {
    /** A manual item: the row is removed. */
    data class Remove(val id: Long) : DeleteOutcome

    /**
     * An item generated by a repeating payment: the row stays and is marked SKIPPED. Removing it would
     * let materialization create it again.
     */
    data class MarkSkipped(val id: Long) : DeleteOutcome
}

/** Pure rules for editing and deleting a SINGLE item (calendar day sheet / Upcoming). Rules are never touched. */
object ItemEdits {
    /** The item is one occurrence of a repeating payment or income source. */
    fun isFromSeries(tx: Transaction): Boolean = tx.recurringRuleId != null

    /**
     * Changes only this row. [Transaction.occurrenceDate] and the rule link are kept, so a moved or
     * re-priced occurrence is still recognised as "already generated" and never duplicated or regenerated.
     */
    fun edit(tx: Transaction, amount: Long, description: String, date: LocalDate): Transaction =
        tx.copy(amount = amount, description = description.trim(), date = date)

    fun delete(tx: Transaction): DeleteOutcome =
        if (isFromSeries(tx)) DeleteOutcome.MarkSkipped(tx.id) else DeleteOutcome.Remove(tx.id)

    /** "Mark as waiting": back to PENDING (undoes Done and Skip). */
    fun markWaiting(tx: Transaction): Transaction = tx.copy(status = TxStatus.PENDING)

    fun canSave(amount: Long?): Boolean = amount != null && amount > 0
}
